#!/usr/bin/env node
// Conformance test for bench/beir/quantize.mjs against golden vectors
// generated by gen-golden-quantization.cpp — a standalone program built
// from the quantization logic copied VERBATIM from
// src/uint8_float_hnsw.hpp:198-234 (the real engine's insert() path),
// compiled with plain g++ (no Emscripten needed; this only tests the
// scalar quantization math, not the WASM bindings).
//
// This turns "quantize.mjs faithfully reimplements the engine" from a
// claim into an assertion: exact q[]/scale/offset match per row, plus the
// affine dot-product identity reproducing the true float dot within
// expected 8-bit quantization error.
//
// To regenerate golden-quantization.json (only needed if
// uint8_float_hnsw.hpp's quantization logic changes):
//   g++ -O2 -std=c++17 gen-golden-quantization.cpp -o gen && ./gen > golden-quantization.json
//
// Usage: node bench/beir/conformance/test-quantization.mjs

import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { quantizeRow, dotQueryAgainstQuantized } from '../quantize.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const golden = JSON.parse(readFileSync(path.join(__dirname, 'golden-quantization.json'), 'utf8'));

let failures = 0;

for (let i = 0; i < golden.length; i++) {
  const row = golden[i];
  const normed = Float32Array.from(row.normalizedRow);
  const result = quantizeRow(normed);

  // Exact match required: same rounding rule, same inputs -> same bytes.
  if (Math.abs(result.scale - row.scale) > 1e-6) {
    console.error(`row ${i}: scale mismatch, got ${result.scale}, expected ${row.scale}`);
    failures++;
  }
  if (Math.abs(result.offset - row.offset) > 1e-6) {
    console.error(`row ${i}: offset mismatch, got ${result.offset}, expected ${row.offset}`);
    failures++;
  }
  for (let d = 0; d < row.q.length; d++) {
    if (result.q[d] !== row.q[d]) {
      console.error(`row ${i} dim ${d}: q byte mismatch, got ${result.q[d]}, expected ${row.q[d]}`);
      failures++;
    }
  }

  // Dot-product identity: offset*sumQuery + scale*(query . q) should
  // reproduce the true float dot product within 8-bit quantization error
  // (max per-dim error is scale/2; with dim=8 and unit-norm vectors the
  // tolerance below is generous but non-vacuous — a broken identity would
  // miss by orders of magnitude, not a rounding epsilon).
  const query = Float32Array.from(row.query);
  const approxDot = dotQueryAgainstQuantized(query, row.sumQuery, result);
  const err = Math.abs(approxDot - row.expectedExactDot);
  if (err > 0.02) {
    console.error(`row ${i}: dot-product identity off by ${err} (approx ${approxDot}, exact ${row.expectedExactDot})`);
    failures++;
  }
}

if (failures > 0) {
  console.error(`FAIL: ${failures} conformance check(s) failed against ${golden.length} golden rows`);
  process.exit(1);
}
console.log(`PASS: quantize.mjs matches src/uint8_float_hnsw.hpp's quantization exactly on ${golden.length} golden rows`);
